def predict_value(r, c, min_r, min_c, max_r, max_c, rule_type='corner'):
    """Predict value based on normalized position"""
    norm_r = (r - min_r) / (max_r - min_r + 1)
    norm_c = (c - min_c) / (max_c - min_c + 1)

    if rule_type == 'corner':
        # Value 2: top-left corner
